--- Makefile
CXX?=c++
CXXFLAGS?=-std=c++17 -O2 -Wall -Wextra -Iinclude
all: textforge
textforge: src/main.cpp src/textforge.cpp
	$(CXX) $(CXXFLAGS) $^ -o $@
test: tests/test.cpp src/textforge.cpp
	$(CXX) $(CXXFLAGS) $^ -o test_textforge && ./test_textforge
clean:
	rm -f textforge test_textforge
--- README
# TextForge 1.4.0
A small C++17 slugification CLI and library. It currently builds with Make.
--- include
#pragma once
#include <string>
namespace textforge { std::string slugify(const std::string&); std::string version(); }
--- src/main
#include "textforge/textforge.hpp"
#include <iostream>
int main(int argc,char**argv){if(argc==2&&std::string(argv[1])=="--version"){std::cout<<"textforge "<<textforge::version()<<"\n";return 0;}if(argc<2){std::cerr<<"usage: textforge TEXT\n";return 2;}std::cout<<textforge::slugify(argv[1])<<"\n";}
--- src/textforge
#include "textforge/textforge.hpp"
#include <cctype>
namespace textforge {
std::string slugify(const std::string& s){std::string o; bool dash=false; for(unsigned char c:s){if(std::isalnum(c)){o+=std::tolower(c);dash=false;}else if(!o.empty()&&!dash){o+='-';dash=true;}}if(!o.empty()&&o.back()=='-')o.pop_back();return o;}
std::string version(){return "1.4.0";}
}
--- tests
#include "textforge/textforge.hpp"
#include <cassert>
int main(){assert(textforge::slugify("Hello, World!")=="hello-world");assert(textforge::slugify("  A  B  ")=="a-b");assert(textforge::version()=="1.4.0");}
